import os
import tempfile
import logging
from pyvirtualdisplay import Display
from taf.managedobject import managedobject
from taf.selenium.gnb.oam.core.webdrivers import CustomWebDriverFirefox, CustomWebDriverChrome


class SeleniumOAMKeywords(managedobject):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _namespace = "seleniumoams"
    DOWNLOAD_DIR_SUFFIX = 'taf_selenium_coam_download'
    DEBUG_DIR_SUFFIX = 'taf_selenium_coam_screenshot'

    def __init__(self):
        super(SeleniumOAMKeywords, self).__init__()
        self._download_dir = None
        self._screenshot_dir = None
        self._virtual_display = None
        self._display = None

    def _set_download_dir(self, download_dir):
        if download_dir and download_dir != '/':
            self._download_dir = download_dir
        else:
            self._download_dir = tempfile.mkdtemp(suffix=self.DOWNLOAD_DIR_SUFFIX)

    def _set_screenshot_dir(self, screenshot_dir):
        if screenshot_dir:
            self._create_screenshot_dir(screenshot_dir)
        else:
            self._create_screenshot_dir(self._download_dir)

    def _create_screenshot_dir(self, dir_path):
        self._screenshot_dir = os.path.join(dir_path, self.DEBUG_DIR_SUFFIX)
        try:
            os.makedirs(self._screenshot_dir)
        except OSError as msg:
            logging.info('screenshot directory exist: {}'.format(msg))
        finally:
            if not os.path.exists(self._screenshot_dir):
                logging.warn('screenshot directory {} is not exist'.format(self._screenshot_dir))

    def _set_browser_parameters(self, download_dir, screenshot_dir, virtual_display):
        self._virtual_display = virtual_display
        self._set_download_dir(download_dir)
        self._set_screenshot_dir(screenshot_dir)
        self.enable_virtual_display()

    def create_firefox_web_driver(self, download_dir, name, **kwargs):

        """
        create web driver for firefox

        :param download_dir: str, path to download directory
        :param name: str, the name representing a web driver instance

        :return: CustomWebDriverFirefox object
        """
        driver = CustomWebDriverFirefox(download_dir, **kwargs)
        self.set_alias(name, driver)
        return driver

    def create_chrome_web_driver(self, download_dir, name, **kwargs):

        """
        create web driver for chrome

        :param download_dir: str, path to download directory
        :param name: str, the name representing a web driver instance

        :return: CustomWebDriverChrome object
        """
        driver = CustomWebDriverChrome(download_dir, **kwargs)
        self.set_alias(name, driver)
        return driver

    def create_firefox_browser(self, name, download_dir=None, screenshot_dir=None, virtual_display=True, **kwargs):

        """
        create browser for firefox

        :param download_dir: path to download directory
        :type download_dir: str
        :param screenshot_dir: path to screenshot directory
        :type screenshot_dir: str
        :param name: the name representing a browser instance
        :type name: str
        :param virtual_display: enable or disable browser window if display on screen, default value is True.
        :type virtual_display: bool

        :return: CustomWebDriverFirefox instance
        """
        self._set_browser_parameters(download_dir, screenshot_dir, virtual_display)
        return self.create_firefox_web_driver(self._download_dir, name, **kwargs)

    def create_chrome_browser(self, name, download_dir=None, screenshot_dir=None, virtual_display=True, **kwargs):

        """
        create browser for chrome

        :param download_dir: path to download directory
        :type download_dir: str
        :param screenshot_dir: path to screenshot directory
        :type screenshot_dir: str
        :param name: the name representing a browser instance
        :type name: str
        :param virtual_display: enable or disable browser window if display on screen, default value is True.
        :type virtual_display: bool

        :return: CustomWebDriverChrome instance
        """
        self._set_browser_parameters(download_dir, screenshot_dir, virtual_display)
        return self.create_chrome_web_driver(self._download_dir, name, **kwargs)

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        Please make sure "xvfb" service is installed on the environment.

        :param width: width of browser, default value is 1920.
        :type width: int
        :param height: int, height of browser, default value is 1280.
        :type height: int
        """
        if self._virtual_display:
            self._display = Display(visible=0, size=(width, height))
            self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        if self._virtual_display:
            self._display.stop()
